//==============================================================================
// Module: stopwatch
// Description: 0-9 BCD Stopwatch with 7-Segment Display Decoder (Active-Low)
// Auto-generated by Spec2RTL Autonomous Engine
//==============================================================================
module stopwatch (
    input  wire       clk,
    input  wire       rst,
    input  wire       start_stop,
    output reg  [3:0] count,
    output reg  [6:0] seg
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 4'd0;
        end else if (start_stop) begin
            if (count >= 4'd9)
                count <= 4'd0;
            else
                count <= count + 4'd1;
        end
    end

    // Active-Low 7-Segment Decoder (a, b, c, d, e, f, g)
    always @(*) begin
        case (count)
            4'd0: seg = 7'b1000000;
            4'd1: seg = 7'b1111001;
            4'd2: seg = 7'b0100100;
            4'd3: seg = 7'b0110000;
            4'd4: seg = 7'b0011001;
            4'd5: seg = 7'b0010010;
            4'd6: seg = 7'b0000010;
            4'd7: seg = 7'b1111000;
            4'd8: seg = 7'b0000000;
            4'd9: seg = 7'b0010000;
            default: seg = 7'b1111111;
        endcase
    end

endmodule
